int handle_kex_init(int type, u_int32_t seq, void *ctxt) {
    ssh_kex_t *kex = ((ssh_session_t *)ctxt)->kex;
    packet_t *pkt = ((ssh_session_t *)ctxt)->pkt_in;

    if (!kex) {
        return SSH_ERROR_INVALID_KEX;
    }

    if (pkt == NULL) {
        return SSH_ERROR_INVALID_PACKET;
    }

    if (pkt->len > 0) {
        packet_discard(pkt);
    }

    if (((ssh_session_t *)ctxt)->kex_state == 0) {
        if (send_kex_init(ctxt) != SSH_OK) {
            return SSH_ERROR_SEND_FAILURE;
        }
    }

    if (select_kex_method(ctxt) != SSH_OK) {
        return SSH_ERROR_METHOD_SELECTION_FAILURE;
    }

    return SSH_OK;
}

int handle_kex_init(int type, u_int32_t seq, void *ctxt) {
    if (!ctxt) {
        return -1;
    }

    struct ssh *ssh = (struct ssh *)ctxt;
    if (!ssh->kex) {
        return -1;
    }

    /* process incoming packet */
    packet_discard_remaining_data();
    ssh->kex->first_kex_follows = packet_get_char();
    ssh->kex->skip_kex = ssh->kex->first_kex_follows;

    if (!ssh->kex->sent_kexinit) {
        send_kex_init(ssh);
        ssh->kex->sent_kexinit = 1;
    }

    /* select appropriate key exchange method and execute */
    if (ssh->kex->method_exchange) {
        return ssh->kex->method_exchange(ssh);
    }

    return 0;
}

int handle_kex_init(int type, u_int32_t seq, void *ctxt) {
    if (!ctxt) {
        return -1; /* Invalid context */
    }

    struct ssh *ssh = ctxt;
    if (!ssh->kex) {
        return -1; /* Invalid key exchange structure */
    }

    /* Process the incoming packet and discard unnecessary data */
    if (buffer_get_ret(ssh->packet, NULL, 0)) {
        return -1; /* Error processing packet */
    }

    if (ssh->kex->first_kex_follows) {
        /* Send key exchange initialization message if not already sent */
        if (!ssh->kex->sent_kexinit) {
            if (kex_send_kexinit(ssh) != 0) {
                return -1; /* Failed to send kexinit */
            }
        }
    }

    /* Select and execute the appropriate key exchange method */
    if (kex_choose_methods(ssh) != 0) {
        return -1; /* Failed to choose kex method */
    }

    return 0; /* Success */
}

int handle_kex_init(int type, u_int32_t seq, void *ctxt) {
    if (!ctxt) {
        return -1;
    }

    struct ssh *ssh = (struct ssh *)ctxt;
    struct kex *kex = ssh->kex;

    if (!kex) {
        return -1;
    }

    if (kex->state != SSH_KEX_STATE_INIT) {
        return -1;
    }

    kex->inited = 1;

    if (!ssh->kex_first) {
        if (ssh_packet_send_kex_init(ssh) < 0) {
            return -1;
        }
    }

    kex->method = kex_select_method(ssh);
    if (!kex->method) {
        return -1;
    }

    if (kex->method->kex_init(kex) < 0) {
        return -1;
    }

    return 0;
}

int handle_kex_init(int type, u_int32_t seq, void *ctxt) {
    ssh_kex *kex = ((ssh_session *)ctxt)->kex;

    if (!kex) {
        return SSH_ERROR;
    }

    packet *pkt = packet_get();

    if (!pkt) {
        return SSH_ERROR;
    }

    packet_discard(pkt);
    ((ssh_session *)ctxt)->kex_follows = 0;

    if (!((ssh_session *)ctxt)->kex_init_sent) {
        int ret = send_kex_init(ctxt);
        if (ret != SSH_OK) {
            return ret;
        }
        ((ssh_session *)ctxt)->kex_init_sent = 1;
    }

    select_kex_method(kex);

    return kex->kex_methods->kex(kex);
}
